  [('rational number', 'A number that can be written as a quotient of two integers with a nonzero divisor.'), ('terminating decimal', 'A decimal that ends, such as 0.375.'), ('repeating decimal', 'A decimal with a digit or group of digits that repeats forever, such as 0.333….')],
  'Thinking negative numbers or repeating decimals are not rational.',
